/**
 * Tiny in-house i18n dictionary. `en` is the source of truth: every other
 * language is typed as a full Record of its keys, so a missing translation
 * fails the build instead of silently falling back at runtime.
 */

export const LANGUAGES = [
  { code: 'en', label: 'English', nativeLabel: 'English', rtl: false },
  { code: 'hi', label: 'Hindi', nativeLabel: 'हिन्दी', rtl: false },
  { code: 'ur', label: 'Urdu', nativeLabel: 'اردو', rtl: true },
  { code: 'ar', label: 'Arabic', nativeLabel: 'العربية', rtl: true },
] as const

export type LanguageCode = (typeof LANGUAGES)[number]['code']

