export const translations: Record<LanguageCode, Record<TranslationKey, string>> = {
  en,
  hi,
  ur,
  ar,
}

export function isLanguageCode(value: string | null): value is LanguageCode {
  return LANGUAGES.some((lang) => lang.code === value)
}

/**
 * Facility names arrive from the API as free-form English labels, so they are
 * matched case-insensitively against the known amenities.
 */
export const FACILITY_KEYS: Record<string, TranslationKey> = {
  'wudu area': 'facility.wuduArea',
  wazu: 'facility.wazu',
  washroom: 'facility.washroom',
  parking: 'facility.parking',
  'two wheeler parking': 'facility.parking2',
  '2 wheeler parking': 'facility.parking2',
  'four wheeler parking': 'facility.parking4',
  '4 wheeler parking': 'facility.parking4',
  'chairs available': 'facility.chairs',
  'chair available': 'facility.chairs',
  chairs: 'facility.chairs',
  'drinking water': 'facility.drinkingWater',
  'drinking water available': 'facility.drinkingWater',
  'water cooler': 'facility.drinkingWater',
  wifi: 'facility.wifi',
  'wheelchair access': 'facility.wheelchair',
  'women section': 'facility.womenSection',
  'women area': 'facility.womenSection',
  'women prayer area': 'facility.womenPrayer',
  library: 'facility.library',
  ac: 'facility.ac',
  'historical site': 'facility.historical',
  wudu: 'facility.wuduArea',
  wudhu: 'facility.wuduArea',
  ablution: 'facility.wuduArea',
  toilet: 'facility.washroom',
  restroom: 'facility.washroom',
  bathroom: 'facility.washroom',
  'wi fi': 'facility.wifi',
  wheelchair: 'facility.wheelchair',
  women: 'facility.womenSection',
  ladies: 'facility.womenSection',
  'ladies section': 'facility.womenSection',
  'air conditioning': 'facility.ac',
  'air conditioner': 'facility.ac',
  historical: 'facility.historical',
}

/** Match a free-form facility label onto a translation key. */
export function facilityTranslationKey(facility: string): TranslationKey | undefined {
  const raw = facility
    .trim()
    .toLowerCase()
    .replace(/[_/]+/g, ' ')
    .replace(/-/g, ' ')
    .replace(/\s+/g, ' ')
  const direct = FACILITY_KEYS[raw]
  if (direct) return direct
  if (/wudhu|wudu|wazu|ablution/.test(raw)) return 'facility.wuduArea'
  if (/wash|toilet|restroom|bathroom/.test(raw)) return 'facility.washroom'
  if (/\bpark/.test(raw) && /(two|2) ?wheel|bike|scooter|motorcycle|moped/.test(raw)) return 'facility.parking2'
  if (/\bpark/.test(raw) && /(four|4) ?wheel|\bcar\b/.test(raw)) return 'facility.parking4'
  if (/\bpark/.test(raw)) return 'facility.parking'
  if (/wi\s*fi|wifi/.test(raw)) return 'facility.wifi'
  if (/wheel/.test(raw)) return 'facility.wheelchair'
  if (/chair/.test(raw)) return 'facility.chairs'
  if (/drink|water cooler|dispenser/.test(raw)) return 'facility.drinkingWater'
  if (/women|ladies|female/.test(raw)) {
    return /prayer|namaz|salah/.test(raw) ? 'facility.womenPrayer' : 'facility.womenSection'
  }
  if (/librar|book/.test(raw)) return 'facility.library'
  if (/^(ac|a c)$|air\s*con|condition/.test(raw)) return 'facility.ac'
  if (/historic/.test(raw)) return 'facility.historical'
  return undefined
}
